do $$ begin
  if not exists (select from pg_roles where rolname = 'pgy_fx_gb_owner') then create role pgy_fx_gb_owner; end if;
  if not exists (select from pg_roles where rolname = 'pgy_fx_gb_admin') then create role pgy_fx_gb_admin; end if;
  if not exists (select from pg_roles where rolname = 'pgy_fx_gb_lead') then create role pgy_fx_gb_lead; end if;
  if not exists (select from pg_roles where rolname = 'pgy_fx_gb_reader') then create role pgy_fx_gb_reader; end if;
end $$;
create schema gb authorization pgy_fx_gb_owner;
grant usage on schema gb to pgy_fx_gb_admin with grant option;
grant usage on schema gb to pgy_fx_gb_reader;
create table gb.doc (id int primary key, body text, note text);
alter table gb.doc owner to pgy_fx_gb_owner;
grant select, update on gb.doc to pgy_fx_gb_admin with grant option;
grant select on gb.doc to pgy_fx_gb_reader;
grant insert (note) on gb.doc to pgy_fx_gb_admin with grant option;
create view gb.v as select id, body from gb.doc;
alter view gb.v owner to pgy_fx_gb_owner;
grant select on gb.v to pgy_fx_gb_admin with grant option;
create sequence gb.seq;
alter sequence gb.seq owner to pgy_fx_gb_owner;
grant usage on sequence gb.seq to pgy_fx_gb_admin with grant option;
create function gb.f() returns int language sql return 1;
alter function gb.f() owner to pgy_fx_gb_owner;
revoke execute on function gb.f() from public;
grant execute on function gb.f() to pgy_fx_gb_admin with grant option;
create type gb.e as enum ('x');
alter type gb.e owner to pgy_fx_gb_owner;
revoke usage on type gb.e from public;
grant usage on type gb.e to pgy_fx_gb_admin with grant option;
grant usage on language plpgsql to pgy_fx_gb_admin with grant option;
set role pgy_fx_gb_admin;
grant usage on schema gb to pgy_fx_gb_lead;
grant select on gb.doc to pgy_fx_gb_lead with grant option;
grant select, update on gb.doc to pgy_fx_gb_reader;
grant insert (note) on gb.doc to pgy_fx_gb_reader;
grant select on gb.v to pgy_fx_gb_reader;
grant usage on sequence gb.seq to pgy_fx_gb_reader;
grant execute on function gb.f() to pgy_fx_gb_reader;
grant usage on type gb.e to pgy_fx_gb_reader;
grant usage on language plpgsql to pgy_fx_gb_reader;
reset role;
set role pgy_fx_gb_lead;
grant select on gb.doc to public;
reset role;
